    68      private List<?> collectItems(Object collectionObj) {
    69          List<?> items;
    70          if (collectionObj instanceof List<?> list) {
    71              items = list;
    72          } else if (collectionObj instanceof Collection<?> collection) {
    73              items = new ArrayList<>(collection);
    74          } else if (collectionObj.getClass().isArray()) {
    75              items = java.util.Arrays.asList((Object[]) collectionObj);
    76          } else {
    77              throw new IllegalArgumentException(
    78                      "The value for itemsProvider '" + itemsProvider + "' must be a Collection or array, but was: "
    79                              + collectionObj.getClass().getName());
    80          }
    81          return items;
    82      }
